#!/bin/sh
# Hand-off from a script bridge to the native bridge (rogue-hook) - SHARED, sourced by every
# sh-side hook, heartbeat, log shipper and updater.
#
#   . "$PLUGIN_ROOT/scripts/native-bridge.sh"
#   rogue_native_handoff "$PLUGIN_ROOT" claude claude "$EVENT"
#
# ONE COPY IS EDITABLE: scripts/shared/native-bridge.sh. Every plugin carries a byte-identical
# copy, regenerated by scripts/sync-shared-scripts.sh and enforced by --check in CI.
#
# The plugin pins one rogue-hook version and the sha256 of each platform build in
# <plugin>/rogue-hook.json. When that version is installed under
# ~/.rogue/bin/rogue-hook/<version>/, the script execs it and never returns: the binary does the
# script's whole job. When it is not, the script starts native-bridge-install.sh detached (which
# downloads, verifies against the pin, and installs it) and carries on doing the job itself, so
# no event ever waits for a download and nothing changes until a verified binary is in place.
#
# No pin, managed hooks, a relative plugin root or a kill switch all mean: stay on the script.
#   ROGUE_NATIVE_BRIDGE=0           every family stays on its script bridge
#   ROGUE_NATIVE_BRIDGE_<FAMILY>=0  one family does (CLAUDE, CODEX, CURSOR, COPILOT, ANTIGRAVITY,
#                                   KIRO, MUSE, GEMINI)
#   ROGUE_NATIVE_BRIDGE_DIR         install root instead of ~/.rogue/bin/rogue-hook
#
# NOTHING RUNS AT SOURCE TIME.

rogue_native_pinned_version() { # <plugin-root>
  sed -n 's/^[[:space:]]*"version"[[:space:]]*:[[:space:]]*"\([0-9][0-9A-Za-z.+-]*\)".*/\1/p' \
    "$1/rogue-hook.json" 2>/dev/null | head -n 1
}

rogue_native_dir() {
  printf '%s' "${ROGUE_NATIVE_BRIDGE_DIR:-$HOME/.rogue/bin/rogue-hook}"
}

# rogue_native_handoff <plugin-root> <family> <rogue-hook args...>
# Returns only when the script bridge should keep the job.
rogue_native_handoff() {
  _rn_root="$1"; _rn_family="$2"
  # Managed hooks read only root-owned files; a user-writable binary must never run for them.
  [ "${ROGUE_HOOK_SOURCE:-}" = managed ] && return 0
  [ "${ROGUE_NATIVE_BRIDGE:-1}" = 0 ] && return 0
  case "$_rn_family" in
    claude)      _rn_off="${ROGUE_NATIVE_BRIDGE_CLAUDE:-1}" ;;
    codex)       _rn_off="${ROGUE_NATIVE_BRIDGE_CODEX:-1}" ;;
    cursor)      _rn_off="${ROGUE_NATIVE_BRIDGE_CURSOR:-1}" ;;
    copilot)     _rn_off="${ROGUE_NATIVE_BRIDGE_COPILOT:-1}" ;;
    antigravity) _rn_off="${ROGUE_NATIVE_BRIDGE_ANTIGRAVITY:-1}" ;;
    kiro)        _rn_off="${ROGUE_NATIVE_BRIDGE_KIRO:-1}" ;;
    muse)        _rn_off="${ROGUE_NATIVE_BRIDGE_MUSE:-1}" ;;
    *)           return 0 ;;
  esac
  [ "$_rn_off" = 0 ] && return 0
  # A relative root resolves against the agent's working directory - a repository could plant
  # its own pin and binary there.
  case "$_rn_root" in /*) ;; *) return 0 ;; esac
  _rn_ver="$(rogue_native_pinned_version "$_rn_root")"
  [ -n "$_rn_ver" ] || return 0
  _rn_bin="$(rogue_native_dir)/$_rn_ver/rogue-hook"
  if [ -f "$_rn_bin" ] && [ -x "$_rn_bin" ]; then
    shift 2
    ROGUE_PLUGIN_ROOT="$_rn_root"; export ROGUE_PLUGIN_ROOT
    exec "$_rn_bin" "$@"
  fi
  if [ -r "$_rn_root/scripts/native-bridge-install.sh" ]; then
    ( nohup sh "$_rn_root/scripts/native-bridge-install.sh" "$_rn_root" \
        </dev/null >/dev/null 2>&1 & ) 2>/dev/null
  fi
  return 0
}
